                {
                    this.UniqueActorReferencesStatic = BinaryOverlayList.FactoryByStartIndexWithTrigger<IUniqueActorReferenceGetter>(
                        stream: stream,
                        package: _package,
                        finalPos: finalPos,
                        itemLength: 12,
