                }
                case RecordTypeInts.DATA:
                {
                    _LocationDataLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)Location_FieldIndex.LocationData;
                }
                case RecordTypeInts.NAM0:
